css:
.foundation{font:14px/1.4 system-ui,sans-serif;color:#e8edf7;background:#111722;border:1px solid #2d3a50;border-radius:14px;padding:18px}
.foundation-head{display:flex;gap:16px;align-items:flex-start;justify-content:space-between;margin-bottom:14px}
.foundation h2{margin:2px 0 0;font-size:22px}.eyebrow{margin:0;color:#8da2c0;text-transform:uppercase;letter-spacing:.12em;font-size:11px}
.direction{font-size:12px;padding:6px 9px;border-radius:999px;background:#202b3e;color:#b8cae4;white-space:nowrap}
.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 14px}.metrics div{background:#161f2e;border:1px solid #2a3850;border-radius:10px;padding:10px}
.metrics strong{display:block;font-size:22px}.metrics span{color:#91a0b5;font-size:12px}
.project-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.project-card{appearance:none;text-align:left;color:inherit;background:#172131;border:1px solid #34445f;border-radius:12px;padding:14px;cursor:pointer;min-width:0}
.project-card:hover{border-color:#6a86b4}.project-card.selected{outline:2px solid #8eb7ff;border-color:#8eb7ff;background:#1b2940}
.card-top{display:flex;justify-content:space-between;gap:8px;align-items:center}.card-top h3{margin:0;font-size:16px;overflow:hidden;text-overflow:ellipsis}
.badge{font-size:11px;border-radius:999px;padding:3px 7px;background:#26354b;color:#cddbf0;text-transform:capitalize}
.card-meta{margin:10px 0 0;color:#9aa9bd;font-size:12px}
@media(max-width:720px){.project-grid{grid-template-columns:1fr}.foundation-head{flex-direction:column}.direction{white-space:normal}}

