const cardHost = root.querySelector('[data-projects]');
function render(){
  const projects = api.getState('projects') || [];
  const activeProjectId = api.getState('activeProjectId');
  const tasks = api.getState('tasks') || [];
  root.querySelector('[data-metric="projects"]').textContent = projects.length;
  root.querySelector('[data-metric="active"]').textContent = projects.filter(p => String(p.status || '').toLowerCase() === 'active').length;
  root.querySelector('[data-metric="open"]').textContent = tasks.filter(t => !['done','closed','complete','completed'].includes(String(t.status || '').toLowerCase())).length;
  cardHost.innerHTML = '';
  projects.slice(0,3).forEach(project => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'project-card' + (project.id === activeProjectId ? ' selected' : '');
    button.setAttribute('aria-pressed', project.id === activeProjectId ? 'true' : 'false');
    const status = project.status || (project.id === activeProjectId ? 'active' : 'planned');
    button.innerHTML = `<div class="card-top"><h3>${project.name || project.title || project.id}</h3><span class="badge">${status}</span></div><p class="card-meta">${project.id === activeProjectId ? 'Current context' : 'Select project'}</p>`;
    button.addEventListener('click', () => {
      api.setState('activeProjectId', project.id);
      api.log(1, `Active project set to ${project.name || project.title || project.id}`);
      render();
    });
    cardHost.appendChild(button);
  });
}
render();
api.subscribe(render);
